// Task Escalation Flow — classify tasks, build markdown report + idempotent CSV log
const todayStr = new Date().toISOString().slice(0, 10);
const today = new Date(todayStr + 'T00:00:00');
const dayMs = 86400000;

function parseDate(s) {
  const d = new Date(String(s).trim() + 'T00:00:00');
  return isNaN(d) ? null : d;
}

let tasks = [];
try {
  tasks = $('Extract Tasks CSV').all().map(i => i.json).filter(r => r && r.task_id);
} catch (e) { tasks = []; }

let existingLog = [];
try {
  existingLog = $('Extract Log CSV').all().map(i => i.json).filter(r => r && r.task_id && r.date);
} catch (e) { existingLog = []; }
const loggedKeys = new Set(existingLog.map(r => r.task_id + '|' + r.date));

const SKIP = new Set(['done', 'cancelled']);
const flagged = [];

for (const t of tasks) {
  const status = String(t.status || '').trim().toLowerCase();
  if (SKIP.has(status)) continue;
  const due = parseDate(t.due_date || '');
  if (!due) continue;
  const diffDays = Math.round((due - today) / dayMs);
  const overdueDays = diffDays < 0 ? -diffDays : 0;
  const blocks = String(t.blocks_milestone || '').trim().toLowerCase() === 'yes';

  let category = null, severity = null;
  if (overdueDays > 7 || blocks)      { category = 'Overdue';      severity = 'Critical'; }
  else if (overdueDays > 0)           { category = 'Overdue';      severity = 'High';     }
  else if (diffDays <= 2)             { category = 'Due in 48h';   severity = 'Medium';   }
  else if (diffDays <= 7)             { category = 'Due this week';severity = 'Medium';   }
  if (!category) continue;

  flagged.push({
    task_id: String(t.task_id), title: String(t.title || ''), owner: String(t.owner || ''),
    status: String(t.status || ''), due_date: String(t.due_date || ''),
    blocks_milestone: String(t.blocks_milestone || ''),
    category, severity, overdue_days: overdueDays
  });
}

const rank = { Critical: 0, High: 1, Medium: 2 };
flagged.sort((a, b) =>
  (rank[a.severity] - rank[b.severity]) ||
  (b.overdue_days - a.overdue_days) ||
  (a.task_id < b.task_id ? -1 : 1));

const counts = { Critical: 0, High: 0, Medium: 0 };
for (const f of flagged) counts[f.severity]++;

let md = '# Task Escalation Report — ' + todayStr + '\n\n';
md += '**Generated:** ' + todayStr + ' · **Tasks scanned:** ' + tasks.length +
      ' · **Flagged:** ' + flagged.length + '\n\n';
md += '| Severity | Count |\n|---|---|\n';
for (const s of ['Critical', 'High', 'Medium']) md += '| ' + s + ' | ' + counts[s] + ' |\n';
md += '\n## Flagged tasks\n\n';
md += '| ID | Title | Owner | Due | Status | Category | Severity | Overdue (d) |\n';
md += '|---|---|---|---|---|---|---|---|\n';
for (const f of flagged) {
  md += '| ' + f.task_id + ' | ' + f.title + ' | ' + f.owner + ' | ' + f.due_date +
        ' | ' + f.status + ' | ' + f.category + ' | **' + f.severity + '** | ' +
        f.overdue_days + ' |\n';
}
md += '\n_Severity rules: Critical = overdue > 7 days or blocks a milestone · ' +
      'High = overdue ≤ 7 days · Medium = due within 48h / this week. ' +
      'Done & Cancelled tasks are excluded._\n';

const newRows = flagged.filter(f => !loggedKeys.has(f.task_id + '|' + todayStr));
const q = v => '"' + String(v ?? '').replace(/"/g, '""') + '"';
const header = 'task_id,date,title,owner,due_date,status,category,severity,overdue_days\n';
let csv = header;
for (const r of existingLog) {
  csv += [r.task_id, r.date, r.title, r.owner, r.due_date, r.status,
          r.category, r.severity, r.overdue_days].map(q).join(',') + '\n';
}
for (const f of newRows) {
  csv += [f.task_id, todayStr, f.title, f.owner, f.due_date, f.status,
          f.category, f.severity, f.overdue_days].map(q).join(',') + '\n';
}

// Convert to binary for the Write nodes
function toBinary(text, fileName, mimeType) {
  return {
    data: Buffer.from(text, 'utf8').toString('base64'),
    mimeType: mimeType,
    fileName: fileName
  };
}
const reportFile = 'escalation-report-' + todayStr + '.md';
return [
  {
    json: {
      report_name: reportFile,
      report_date: todayStr,
      tasks_scanned: tasks.length,
      flagged: flagged.length,
      new_log_rows: newRows.length,
      critical: counts.Critical, high: counts.High, medium: counts.Medium
    },
    binary: {
      report: toBinary(md, reportFile, 'text/markdown'),
      log: toBinary(csv, 'escalation-log.csv', 'text/csv')
    }
  }
];
